def __init__(self, func: Callable[..., Any], arg_types: Dict[str, type],
    return_type: Optional[type]=None, yield_type: Optional[type]=None) ->None:
    self.func = func
    self.arg_types = arg_types
    self.return_type = return_type
    self.yield_type = yield_type

def __hash__(self) ->int:
    return hash(
        (
            self.func,
            frozenset(self.arg_types.items()),
            self.return_type,
            self.yield_type,
        )
    )
